@import "tailwindcss";

@theme {
  /* Instrument Sans (index.html), one typeface for everything. */
  --font-sans: "Instrument Sans", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --color-ground: #fbfbfa;
  --color-ink: #18181a;
  --color-ink-2: #5d5d63;
  --color-ink-3: #93939a;
  --color-line: #ececea;
  --color-hair: #ececea;
  --color-panel: #f3f3f1;
  --color-soft: #f3f3f1;
  /* The one blue: the primary button and the selected item. */
  --color-ok: #2348d0;
  --color-accent: #2348d0;
  --color-warn: #b45309;
  /* Only the late or short number. */
  --color-stop: #c8321f;
  --color-late: #c8321f;
  --color-silent: #93939a;
  /* Work a routine did on its own. */
  --color-routine: #16795d;
  /* A supplier answered. */
  --color-good: #16795d;
  /* The highlighter: only on source crops. */
  --color-mark: #ffe066;
  --color-land: #ededea;
}

html, body, #root { height: 100%; }
body {
  background: var(--color-ground);
  color: var(--color-ink);
  font-family: var(--font-sans);
  font-variant-numeric: tabular-nums;
  -webkit-font-smoothing: antialiased;
}

@keyframes pulse-ring {
  0% { r: 5px; opacity: .9; }
  100% { r: 20px; opacity: 0; }
}
.pulse-ring { animation: pulse-ring 1.6s ease-out infinite; }
.pulse-once { animation: pulse-ring 1.2s ease-out 3; }
.pulse-once.delay { animation-delay: .5s; }

@keyframes recolour {
  0% { stroke-width: 7px; }
  100% { stroke-width: 2.75px; }
}
.route-recolour { animation: recolour 1.2s ease-out; }

@keyframes slide-in {
  from { opacity: 0; transform: translateY(-14px); }
  to { opacity: 1; transform: none; }
}
.slide-in { animation: slide-in .45s ease-out; }

@keyframes toast-in {
  from { opacity: 0; transform: translate(-50%, -8px); }
  to { opacity: 1; transform: translate(-50%, 0); }
}
.toast-in { animation: toast-in .25s ease-out; }

/* Detail pane: fade the next decision in instead of jumping. */
@keyframes pane-in {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: none; }
}
.pane-in { animation: pane-in .2s ease-out; }

.scroll-thin { scrollbar-width: thin; scrollbar-color: var(--color-line) transparent; }

kbd {
  font-family: var(--font-sans);
  font-size: 12px;
  font-weight: 600;
  padding: 1px 6px;
  border-radius: 5px;
  border: 1px solid var(--color-line);
  border-bottom-width: 2px;
  background: #fff;
  color: var(--color-ink-2);
}

/* The Routines button (Routines.tsx) dressed as a header tab or a menu row. Unlayered, so it
   wins over the button's own utilities without touching that component. */
.tab-routines > button {
  height: 2rem;
  border: 0;
  border-radius: 6px;
  background: transparent;
  padding: 0 12px;
}
.tab-routines > button:hover { background: transparent; color: var(--color-ink); }
.tab-routines-menu > button {
  width: 100%;
  height: 2.5rem;
  justify-content: flex-start;
  border: 0;
  border-radius: 8px;
  padding: 0 8px;
  font-size: 15px;
}
.tab-routines-menu > button > span.hidden { display: inline; }

/* Today: three sizes per viewport. */
:root { --big: 27px; --body: 17px; --small: 13px; }
@media (min-width: 1024px) { :root { --big: 34px; --body: 18px; --small: 13.5px; } }

.t-big { font-size: var(--big); line-height: 1.2; font-weight: 600; letter-spacing: -0.025em; }
.t-body { font-size: var(--body); line-height: 1.6; }
.t-small { font-size: var(--small); line-height: 1.5; }

/* A grounded number: dotted underline, tap to see where it was read. */
.cite {
  color: var(--color-ink); font-weight: 500; cursor: pointer;
  border-bottom: 1.5px dotted var(--color-ink-3); padding-bottom: 1px;
  background: none; font: inherit; font-weight: 500; text-align: left;
}
.cite.late { color: var(--color-late); border-bottom-color: color-mix(in srgb, var(--color-late) 55%, transparent); }
.cite:hover, .cite[aria-expanded="true"] { border-bottom-style: solid; }
.cite:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 3px; border-radius: 2px; }
.cite svg { display: inline; width: 13px; height: 13px; margin-left: 3px; color: var(--color-ink-3); vertical-align: 0; }

.uline { color: var(--color-ink-2); border-bottom: 1px solid var(--color-hair); cursor: pointer; }
.uline:hover { color: var(--color-ink); border-bottom-color: var(--color-ink-3); }
.uline:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 3px; }
.dot-routine::before { content: ""; display: inline-block; width: 6px; height: 6px; border-radius: 50%; background: var(--color-routine); margin-right: 8px; vertical-align: 2px; }

@keyframes rise { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }
.rise { animation: rise .28s ease-out; }
@keyframes sheet-up { from { transform: translateY(24px); opacity: 0; } to { transform: none; opacity: 1; } }
.sheet-up { animation: sheet-up .22s ease-out; }
@keyframes fade { from { opacity: 0; } to { opacity: 1; } }
.fade { animation: fade .2s ease-out; }
@media (prefers-reduced-motion: reduce) { .rise, .sheet-up, .fade, .pane-in, .slide-in, .pulse-ring, .pulse-once { animation: none; } }
import { Loader2 } from 'lucide-react'
import { useCallback, useEffect, useRef, useState } from 'react'
import { fmtDay, fmtTime, type State } from '@/lib/api'
import { headlineOf } from '@/lib/today'
import { cn } from '@/lib/utils'
import { hideDraft, pendingOf, refreshLive, refreshNow, useLive } from './routines/live'
import { ProposalLines, ProposalSheet, groupProposals } from './routines/Proposals'
import { RoutineCard } from './routines/RoutineCard'
import { body, call, type Mode, type Proposal, type Routine, type Run } from './routines/types'

// The Routines page (/routines). Routines the agents wrote after a person decided something by
// hand: a recipe of conditions and steps, compiled to small Python and run in the Monty sandbox
// on every check (routines.py). Here they are reviewed, changed, switched on or off, and drafted
// from a decision. Same calm language as Today: one centred column, whitespace instead of frames,
// three type sizes, green only for work a routine did. Every routine is one view: the
// When / Then / Always diagram that is also its editor.
//
// Links in: /routines?draft=<cardId> drafts a routine from that decision ("Show me how" on
// Today) and shows it first; /routines?routine=<id> scrolls to that routine ("How it decided").

const DECIDED: Record<string, string> = {
  approved: 'Approved', sent: 'Sent', escalated: 'Passed on', dismissed: 'Dismissed',
}

/** Keeps proposals, drafts and "would handle" in step with the app's refresh, on every page. */
export function RoutinesLive({ state }: { state: State }) {
  useEffect(() => { void refreshLive() }, [state.now, state.last_check_at])
  return null
}

export function Routines({ state, onChanged, phone }: { state: State; onChanged: () => void; phone?: boolean }) {
  const [items, setItems] = useState<Routine[] | null>(null)
  const [draft, setDraft] = useState<{ routine: Routine; preview: Run } | null>(null)
  const [writing, setWriting] = useState<string | null>(null)
  const [error, setError] = useState('')
  const [review, setReview] = useState<Proposal[] | null>(null)
  const [voiceEdits, setVoiceEdits] = useState<Record<string, { routine: Routine; preview: Run }>>({})
  const [target, setTarget] = useState<string | null>(null)
  const tested = useRef(new Set<string>())
  const top = useRef<HTMLDivElement>(null)

  const load = useCallback(async () => {
    try {
      const r = await fetch('/api/routines')
      if (r.ok) setItems((await r.json()).routines)
    } catch { /* offline for a moment: keep the last list */ }
  }, [])
  useEffect(() => {
    void load()
    void refreshNow()
    const t = window.setInterval(load, 15000)
    return () => clearInterval(t)
  }, [load])
  const live = useLive()
  const proposals = pendingOf(live)
  const groups = groupProposals(proposals, state)

  // Links in: draft from a decision, or show one routine. Read once per URL, then cleaned up.
  const search = window.location.search
  useEffect(() => {
    const q = new URLSearchParams(search)
    const cardId = q.get('draft')
    const rid = q.get('routine')
    if (!cardId && !rid) return
    window.history.replaceState(null, '', '/routines')
    if (cardId) { void suggest(cardId); top.current?.scrollIntoView({ block: 'start' }) }
    if (rid) setTarget(rid)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [search])
  useEffect(() => {
    if (!target || !items) return
    const el = document.getElementById(`routine-${target}`)
    if (el) { el.scrollIntoView({ block: 'start', behavior: 'smooth' }); window.setTimeout(() => setTarget(null), 2400) }
  }, [target, items])

  const list = items ?? []
  const waiting = live.drafts.filter((d) => !list.some((r) => r.id === d.routine.id) && draft?.routine.id !== d.routine.id)
  // Test each waiting voice draft once on today's inbox (its stored test may be hours old).
  useEffect(() => {
    for (const d of waiting) {
      const id = d.routine.id
      if (tested.current.has(id) || voiceEdits[id] || !d.routine.spec) continue
      tested.current.add(id)
      call<{ routine: Routine; preview: Run }>('/api/routines/preview', body(d.routine))
        .then((out) => setVoiceEdits((v) => (v[id] ? v : { ...v, [id]: { routine: { ...d.routine, code: out.routine.code }, preview: out.preview } })))
        .catch(() => { /* keep the stored test run */ })
    }
  }, [waiting, voiceEdits])

  // Decisions made by hand; a card with a routine says so, the card behind an open draft is hidden.
  const automatedBy = new Map(list.filter((r) => r.created_from).map((r) => [r.created_from!, r.name]))
  const drafting = new Set([draft?.routine.created_from, writing, ...waiting.map((d) => d.card_id)])
  const decided = state.cards.filter((c) => c.status in DECIDED && !drafting.has(c.id))
  const writingCard = state.cards.find((c) => c.id === writing)

  async function suggest(cardId: string) {
    setWriting(cardId); setError(''); setDraft(null)
    top.current?.scrollIntoView({ block: 'start', behavior: 'smooth' })
    try {
      setDraft(await call<{ routine: Routine; preview: Run }>('/api/routines/suggest', { card_id: cardId }))
    } catch (e) {
      setError(`The agent could not write a routine: ${(e as Error).message}.`)
    } finally { setWriting(null) }
  }
  /** Save a draft; a new routine starts by asking unless the buyer chose otherwise. */
  const save = (routine: Routine, mode: Mode) => call('/api/routines', { ...body(routine), mode })
  async function turnOn(mode: Mode) {
    if (!draft) return
    const id = draft.routine.id
    await save(draft.routine, mode)
    setDraft(null)
    await load()
    setTarget(id)
    onChanged()
  }
  const changed = () => { void load(); void refreshNow(); onChanged() }
  const label = (text: string) => <h2 className="t-small text-ink-3">{text}</h2>

  return (
    <main className={cn('mx-auto w-full max-w-[1040px] pb-32', phone ? 'px-6 pt-6' : 'px-12 pt-16')}>
      <div ref={top} className="scroll-mt-24" />
      <h1 className="t-big text-ink">Routines</h1>
      <p className="t-body mt-4 max-w-[640px] text-ink-2">
        Written by an agent from your decisions. They run in a closed sandbox on every check. Anything that costs money or changes the plan still comes to you.
      </p>

      {groups.length > 0 && (
        <section className="mt-12 space-y-3" aria-label="Waiting for your OK">
          {label('Waiting for your OK')}
          <ProposalLines groups={groups} onReview={setReview} max={6} />
        </section>
      )}

      {(writing || draft || error) && (
        <section className="mt-14" aria-label="Handle them the same way">
          {writing && (
            <div className="rise">
              {label('Writing a routine from your decision')}
              <p className="t-body mt-3 flex items-center gap-2.5 text-ink"><Loader2 size={17} className="animate-spin text-ink-3" /> One moment…</p>
              <p className="t-small mt-2 max-w-[640px] text-ink-2">
                {writingCard ? <>From “{headlineOf(writingCard, state)}” </> : null}
                The agent writes the steps, checks them in the sandbox and tests them on today's inbox before you see them. Up to half a minute.
              </p>
            </div>
          )}
          {draft && (
            <div className="rise">
              <RoutineCard
                key={`draft-${draft.routine.id}`}
                big
                routine={draft.routine}
                onChanged={changed}
                draft={{
                  preview: draft.preview,
                  onTurnOn: turnOn,
                  onDiscard: () => setDraft(null),
                  onReplace: (routine, preview) => setDraft({ routine, preview }),
                }}
              />
            </div>
          )}
          {error && <p className="t-small text-late" role="alert">{error}</p>}
        </section>
      )}

      {waiting.length > 0 && (
        <section className="mt-16 space-y-14" aria-label="Drafted from your call">
          {label('Drafted from your call')}
          {waiting.map((d) => {
            const id = d.routine.id
            const cur = voiceEdits[id] ?? { routine: d.routine, preview: d.preview ?? { at: d.at ?? '', ok: true, dry: true } }
            return (
              <div key={`voice-${id}`}>
                {d.instruction && <p className="t-body mb-5 text-ink-2">You said: <span className="text-ink">“{d.instruction}”</span></p>}
                <RoutineCard
                  routine={cur.routine}
                  onChanged={changed}
                  draft={{
                    preview: cur.preview,
                    onTurnOn: async (mode) => { await save(cur.routine, mode); hideDraft(id); await load(); onChanged() },
                    onDiscard: () => hideDraft(id),
                    onReplace: (routine, preview) => setVoiceEdits((v) => ({ ...v, [id]: { routine, preview } })),
                  }}
                />
              </div>
            )
          })}
        </section>
      )}

      <section className="mt-16" aria-label="Your routines">
        {label('Your routines')}
        {items && list.length === 0 && !draft && !writing && (
          <p className="t-body mt-3 text-ink-2">No routines yet. Decide something, then let the agent handle the next one like it.</p>
        )}
        <div className="mt-8 space-y-20">
          {list.map((r) => (
            <div key={r.id} id={`routine-${r.id}`} className={cn('scroll-mt-24 rounded-2xl transition-shadow duration-700', target === r.id && 'shadow-[0_0_0_12px_var(--color-soft)] bg-soft')}>
              <RoutineCard routine={r} onChanged={changed} />
            </div>
          ))}
        </div>
      </section>

      <section className="mt-20" aria-label="Automate a decision you made">
        {label('Automate a decision you made')}
        {decided.length === 0 && <p className="t-small mt-3 text-ink-3">{draft ? 'Review the suggestion above.' : 'Nothing decided yet.'}</p>}
        <ul className="mt-2">
          {decided.map((c) => (
            <li key={c.id} className="flex items-baseline justify-between gap-6 py-3">
              <div className="min-w-0">
                <div className="t-body line-clamp-2 text-ink">{headlineOf(c, state)}</div>
                <div className="t-small text-ink-3">
                  {DECIDED[c.status]}{c.ui?.at ? ` · ${fmtDay(c.ui.at)} ${fmtTime(c.ui.at)}` : ''}
                </div>
              </div>
              {automatedBy.has(c.id) ? (
                <span className="t-small dot-routine max-w-[45%] shrink-0 text-right text-routine">‘{automatedBy.get(c.id)}’</span>
              ) : (
                <button className="t-small uline shrink-0 disabled:opacity-60" disabled={!!writing} onClick={() => void suggest(c.id)}>
                  Handle cases like this
                </button>
              )}
            </li>
          ))}
        </ul>
      </section>

      <ProposalSheet items={review} ctx={state} onClose={() => setReview(null)} onChanged={changed} />
    </main>
  )
}
// Shapes of /api/routines (src/ask_soony/routines.py) and small helpers shared by the routine UI.

export type Field =
  | 'evidence' | 'headline' | 'option_action' | 'option_to' | 'supplier_name' | 'kind'
  | 'hours_left' | 'waiting_hours' | 'has_reply' | 'reply_after_launch' | 'silent_hours'
export type Channel = 'phone' | 'teams' | 'both'
/** What a routine looks at on each check. Missing means open decisions. */
export type Trigger = 'decisions' | 'waiting' | 'shipments'
/** How much a routine may do on its own. Missing means "tell". */
export type Mode = 'ask' | 'tell' | 'quiet'
export type StepKind = 'carry_out' | 'notify' | 'log' | 'chase' | 'call' | 'ask_status'

export interface Cond {
  id: string; field: Field; op: 'contains' | 'is' | 'any_of' | 'lt' | 'gt'; value: string | number | boolean; text: string
}
export interface Step {
  id: string
  do: StepKind
  text: string
  match?: { to?: string; action_contains?: string }
  channel?: Channel
  message?: string
}
export interface Spec { on?: Trigger; when: Cond[]; then: Step[] }

export interface Did {
  do: StepKind
  card?: string; shipment?: string; option?: string; text?: string; channel?: Channel; status?: string; dry?: boolean
}
export interface Run { at: string; ok: boolean; dry?: boolean; result?: unknown; error?: string; log?: string[]; did?: Did[] }
export interface Routine {
  id: string; name: string; description: string; spec?: Spec | null; code: string; enabled: boolean
  mode?: Mode
  created_from?: string | null; created_at?: string; runs?: Run[]; handled?: number; note?: string
}

/** Something a routine in "ask me" mode prepared and waits to be confirmed (GET /api/routines/proposals). */
export interface Proposal {
  id: string
  routine_id: string
  routine_name: string
  card_id?: string | null
  shipment_id?: string | null
  step: { do: StepKind | string; text?: string; channel?: Channel; [k: string]: unknown }
  preview_text?: string | null
  created_at?: string
  status: 'pending' | 'done' | 'skipped'
}
/** A routine that matches a card (GET /api/routines/would-handle). */
export interface WouldHandle { routine_id: string; routine_name: string; mode?: Mode; enabled: boolean }

export const MODES: { key: Mode; label: string; hint: string }[] = [
  { key: 'ask', label: 'Ask me', hint: 'Prepares it, you confirm with one tap' },
  { key: 'tell', label: 'Do it and tell me', hint: 'Does it and tells you' },
  { key: 'quiet', label: 'Do it quietly', hint: 'Does it, you see it in Handled for you' },
]
export const modeOf = (r: Pick<Routine, 'mode'>): Mode => (r.mode === 'ask' || r.mode === 'quiet' ? r.mode : 'tell')

/** The trigger node: what the routine looks at, in the buyer's words. */
export function triggerText(on?: Trigger): { title: string; text: string } {
  if (on === 'waiting') return { title: 'Messages still waiting for an answer', text: 'Every portal check, the emails we sent that have no reply yet' }
  if (on === 'shipments') return { title: 'Shipments that stopped updating', text: 'Every portal check, shipments with no new status for a while' }
  return { title: 'Every portal check · open decisions', text: 'New files, replies and open decisions, about every minute' }
}

const hoursWord = (v: unknown) => {
  const n = Number(v)
  if (!Number.isFinite(n)) return String(v)
  return n < 1 ? `${Math.round(n * 60)} min` : `${Math.round(n * 10) / 10} h`
}
const yes = (v: unknown) => v === true || /^(yes|true|1)$/i.test(String(v))

/**
 * A condition as a buyer reads it. The recipe's own text wins; the numeric and yes/no fields get
 * plain words when it is missing, so a field name never reaches the screen.
 */
export function condWords(c: Cond): string {
  if (c.text?.trim()) return c.text
  const more = c.op === 'gt'
  switch (c.field) {
    case 'hours_left': return `${more ? 'More' : 'Less'} than ${hoursWord(c.value)} before the deadline`
    case 'waiting_hours': return `No answer for ${more ? 'more' : 'less'} than ${hoursWord(c.value)}`
    case 'silent_hours': return `No shipment update for ${more ? 'more' : 'less'} than ${hoursWord(c.value)}`
    case 'has_reply': return yes(c.value) ? 'The supplier has answered' : 'The supplier has not answered yet'
    case 'reply_after_launch': return yes(c.value) ? 'The answer promises a date after launch' : 'The answer promises a date before launch'
    default: return `${c.op === 'contains' ? 'Mentions' : 'Is'} ${String(c.value)}`
  }
}

/** The fields the save, edit and preview endpoints take. */
export const body = (r: Routine) => ({
  id: r.id, name: r.name, description: r.description, spec: r.spec, created_from: r.created_from ?? null,
})

/** POST that keeps the server's reason on failure (FastAPI puts it in `detail`). */
export async function call<T>(url: string, payload: unknown = {}, method = 'POST'): Promise<T> {
  const r = await fetch(url, {
    method, headers: { 'Content-Type': 'application/json' }, body: method === 'DELETE' ? undefined : JSON.stringify(payload),
  })
  if (!r.ok) {
    let reason = ''
    try { reason = String((await r.json()).detail ?? '') } catch { /* not JSON */ }
    throw new Error(reason || `the server answered ${r.status}`)
  }
  return r.json()
}

export const newId = (prefix: string) => `${prefix}${Math.random().toString(36).slice(2, 8)}`

/** Steps a buyer can add with one click or drag. */
export const PALETTE: { key: string; label: string; make: () => Step }[] = [
  { key: 'phone', label: 'Tell me on my phone', make: () => ({ id: newId('s'), do: 'notify', channel: 'phone', message: '{headline}', text: 'Tell me on my phone' }) },
  { key: 'teams', label: 'Tell me on Teams', make: () => ({ id: newId('s'), do: 'notify', channel: 'teams', message: '{headline}', text: 'Tell me on Teams' }) },
  { key: 'call', label: 'Call me', make: () => ({ id: newId('s'), do: 'call', text: 'Call me' }) },
  { key: 'chase', label: 'Chase once if no answer', make: () => ({ id: newId('s'), do: 'chase', text: 'Chase once in the same thread if there is no answer' }) },
  { key: 'log', label: 'Note it in the history', make: () => ({ id: newId('s'), do: 'log', message: 'Handled by a routine: {headline}', text: 'Note it in the history' }) },
  { key: 'ask_status', label: 'Ask for a status', make: () => ({ id: newId('s'), do: 'ask_status', text: 'Ask the supplier for the shipment status' }) },
]

export function paletteKey(s: Step): string | null {
  if (s.do === 'log' || s.do === 'chase' || s.do === 'call' || s.do === 'ask_status') return s.do
  if (s.do === 'notify' && (s.channel === 'phone' || s.channel === 'teams')) return s.channel
  return null
}

const where = (c?: Channel) => (c === 'phone' ? ' on your phone' : c === 'teams' ? ' on Teams' : '')

export type LineKind = 'send' | 'tell' | 'note' | 'chase' | 'call' | 'ask_status'

/** One line per thing a run did (or would do, in a test run). */
export function didLines(run: Run, spec?: Spec | null): { kind: LineKind; channel?: Channel; text: string }[] {
  const out: { kind: LineKind; channel?: Channel; text: string }[] = []
  for (const d of run.did ?? []) {
    const about = d.text || d.option || ''
    if (d.do === 'carry_out') {
      out.push({ kind: 'send', text: `${d.dry ? 'Would send' : 'Sent'}: ${d.option ?? 'the message'}` })
    } else if (d.do === 'chase') {
      out.push({ kind: 'chase', text: `${d.dry ? 'Would chase' : 'Chased'} once in the same thread${about ? `: ${about}` : ''}` })
    } else if (d.do === 'call') {
      out.push({ kind: 'call', text: `${d.dry ? 'Would call you' : 'Called you'}${about ? `: ${about}` : ''}` })
    } else if (d.do === 'ask_status') {
      out.push({ kind: 'ask_status', text: `${d.dry ? 'Would ask' : 'Asked'} for a status${about ? `: ${about}` : ''}` })
    } else if (d.do === 'log') {
      out.push({ kind: 'note', text: `${d.dry ? 'Would note' : 'Noted'}: ${about}` })
    } else {
