import { Loader2 } from 'lucide-react'
import { useCallback, useEffect, useRef, useState } from 'react'
import { fmtDay, fmtTime, type State } from '@/lib/api'
import { headlineOf } from '@/lib/today'
import { cn } from '@/lib/utils'
import { hideDraft, pendingOf, refreshLive, refreshNow, useLive } from './routines/live'
import { ProposalLines, ProposalSheet, groupProposals } from './routines/Proposals'
import { RoutineCard } from './routines/RoutineCard'
import { body, call, type Mode, type Proposal, type Routine, type Run } from './routines/types'

// The Routines page (/routines). Routines the agents wrote after a person decided something by
// hand: a recipe of conditions and steps, compiled to small Python and run in the Monty sandbox
// on every check (routines.py). Here they are reviewed, changed, switched on or off, and drafted
// from a decision. Same calm language as Today: one centred column, whitespace instead of frames,
// three type sizes, green only for work a routine did. Every routine is one view: the
// When / Then / Always diagram that is also its editor.
//
// Links in: /routines?draft=<cardId> drafts a routine from that decision ("Show me how" on
// Today) and shows it first; /routines?routine=<id> scrolls to that routine ("How it decided").

const DECIDED: Record<string, string> = {
  approved: 'Approved', sent: 'Sent', escalated: 'Passed on', dismissed: 'Dismissed',
}

/** Keeps proposals, drafts and "would handle" in step with the app's refresh, on every page. */
export function RoutinesLive({ state }: { state: State }) {
  useEffect(() => { void refreshLive() }, [state.now, state.last_check_at])
  return null
}

export function Routines({ state, onChanged, phone }: { state: State; onChanged: () => void; phone?: boolean }) {
  const [items, setItems] = useState<Routine[] | null>(null)
  const [draft, setDraft] = useState<{ routine: Routine; preview: Run } | null>(null)
  const [writing, setWriting] = useState<string | null>(null)
  const [error, setError] = useState('')
  const [review, setReview] = useState<Proposal[] | null>(null)
  const [voiceEdits, setVoiceEdits] = useState<Record<string, { routine: Routine; preview: Run }>>({})
  const [target, setTarget] = useState<string | null>(null)
  const tested = useRef(new Set<string>())
  const top = useRef<HTMLDivElement>(null)

  const load = useCallback(async () => {
    try {
      const r = await fetch('/api/routines')
      if (r.ok) setItems((await r.json()).routines)
    } catch { /* offline for a moment: keep the last list */ }
  }, [])
  useEffect(() => {
    void load()
    void refreshNow()
    const t = window.setInterval(load, 15000)
    return () => clearInterval(t)
  }, [load])
  const live = useLive()
  const proposals = pendingOf(live)
  const groups = groupProposals(proposals, state)

  // Links in: draft from a decision, or show one routine. Read once per URL, then cleaned up.
  const search = window.location.search
  useEffect(() => {
    const q = new URLSearchParams(search)
    const cardId = q.get('draft')
    const rid = q.get('routine')
    if (!cardId && !rid) return
    window.history.replaceState(null, '', '/routines')
    if (cardId) { void suggest(cardId); top.current?.scrollIntoView({ block: 'start' }) }
    if (rid) setTarget(rid)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [search])
  useEffect(() => {
    if (!target || !items) return
    const el = document.getElementById(`routine-${target}`)
    if (el) { el.scrollIntoView({ block: 'start', behavior: 'smooth' }); window.setTimeout(() => setTarget(null), 2400) }
  }, [target, items])

  const list = items ?? []
  const waiting = live.drafts.filter((d) => !list.some((r) => r.id === d.routine.id) && draft?.routine.id !== d.routine.id)
  // Test each waiting voice draft once on today's inbox (its stored test may be hours old).
  useEffect(() => {
    for (const d of waiting) {
      const id = d.routine.id
      if (tested.current.has(id) || voiceEdits[id] || !d.routine.spec) continue
      tested.current.add(id)
      call<{ routine: Routine; preview: Run }>('/api/routines/preview', body(d.routine))
        .then((out) => setVoiceEdits((v) => (v[id] ? v : { ...v, [id]: { routine: { ...d.routine, code: out.routine.code }, preview: out.preview } })))
        .catch(() => { /* keep the stored test run */ })
    }
  }, [waiting, voiceEdits])

  // Decisions made by hand; a card with a routine says so, the card behind an open draft is hidden.
  const automatedBy = new Map(list.filter((r) => r.created_from).map((r) => [r.created_from!, r.name]))
  const drafting = new Set([draft?.routine.created_from, writing, ...waiting.map((d) => d.card_id)])
  const decided = state.cards.filter((c) => c.status in DECIDED && !drafting.has(c.id))
  const writingCard = state.cards.find((c) => c.id === writing)

  async function suggest(cardId: string) {
    setWriting(cardId); setError(''); setDraft(null)
    top.current?.scrollIntoView({ block: 'start', behavior: 'smooth' })
    try {
      setDraft(await call<{ routine: Routine; preview: Run }>('/api/routines/suggest', { card_id: cardId }))
    } catch (e) {
      setError(`The agent could not write a routine: ${(e as Error).message}.`)
    } finally { setWriting(null) }
  }
  /** Save a draft; a new routine starts by asking unless the buyer chose otherwise. */
  const save = (routine: Routine, mode: Mode) => call('/api/routines', { ...body(routine), mode })
  async function turnOn(mode: Mode) {
    if (!draft) return
    const id = draft.routine.id
    await save(draft.routine, mode)
    setDraft(null)
    await load()
    setTarget(id)
    onChanged()
  }
  const changed = () => { void load(); void refreshNow(); onChanged() }
  const label = (text: string) => <h2 className="t-small text-ink-3">{text}</h2>

  return (
    <main className={cn('mx-auto w-full max-w-[1040px] pb-32', phone ? 'px-6 pt-6' : 'px-12 pt-16')}>
      <div ref={top} className="scroll-mt-24" />
      <h1 className="t-big text-ink">Routines</h1>
      <p className="t-body mt-4 max-w-[640px] text-ink-2">
        Written by an agent from your decisions. They run in a closed sandbox on every check. Anything that costs money or changes the plan still comes to you.
      </p>

      {groups.length > 0 && (
        <section className="mt-12 space-y-3" aria-label="Waiting for your OK">
          {label('Waiting for your OK')}
          <ProposalLines groups={groups} onReview={setReview} max={6} />
        </section>
      )}

      {(writing || draft || error) && (
        <section className="mt-14" aria-label="Handle them the same way">
          {writing && (
            <div className="rise">
              {label('Writing a routine from your decision')}
              <p className="t-body mt-3 flex items-center gap-2.5 text-ink"><Loader2 size={17} className="animate-spin text-ink-3" /> One moment…</p>
              <p className="t-small mt-2 max-w-[640px] text-ink-2">
                {writingCard ? <>From “{headlineOf(writingCard, state)}” </> : null}
                The agent writes the steps, checks them in the sandbox and tests them on today's inbox before you see them. Up to half a minute.
              </p>
            </div>
          )}
          {draft && (
            <div className="rise">
              <RoutineCard
                key={`draft-${draft.routine.id}`}
                big
                routine={draft.routine}
                onChanged={changed}
                draft={{
                  preview: draft.preview,
                  onTurnOn: turnOn,
                  onDiscard: () => setDraft(null),
                  onReplace: (routine, preview) => setDraft({ routine, preview }),
                }}
              />
            </div>
          )}
          {error && <p className="t-small text-late" role="alert">{error}</p>}
        </section>
      )}

      {waiting.length > 0 && (
        <section className="mt-16 space-y-14" aria-label="Drafted from your call">
          {label('Drafted from your call')}
          {waiting.map((d) => {
            const id = d.routine.id
            const cur = voiceEdits[id] ?? { routine: d.routine, preview: d.preview ?? { at: d.at ?? '', ok: true, dry: true } }
            return (
              <div key={`voice-${id}`}>
                {d.instruction && <p className="t-body mb-5 text-ink-2">You said: <span className="text-ink">“{d.instruction}”</span></p>}
                <RoutineCard
                  routine={cur.routine}
                  onChanged={changed}
                  draft={{
                    preview: cur.preview,
                    onTurnOn: async (mode) => { await save(cur.routine, mode); hideDraft(id); await load(); onChanged() },
                    onDiscard: () => hideDraft(id),
                    onReplace: (routine, preview) => setVoiceEdits((v) => ({ ...v, [id]: { routine, preview } })),
                  }}
                />
              </div>
            )
          })}
        </section>
      )}

      <section className="mt-16" aria-label="Your routines">
        {label('Your routines')}
        {items && list.length === 0 && !draft && !writing && (
          <p className="t-body mt-3 text-ink-2">No routines yet. Decide something, then let the agent handle the next one like it.</p>
        )}
        <div className="mt-8 space-y-20">
          {list.map((r) => (
            <div key={r.id} id={`routine-${r.id}`} className={cn('scroll-mt-24 rounded-2xl transition-shadow duration-700', target === r.id && 'shadow-[0_0_0_12px_var(--color-soft)] bg-soft')}>
              <RoutineCard routine={r} onChanged={changed} />
            </div>
          ))}
        </div>
      </section>

      <section className="mt-20" aria-label="Automate a decision you made">
        {label('Automate a decision you made')}
        {decided.length === 0 && <p className="t-small mt-3 text-ink-3">{draft ? 'Review the suggestion above.' : 'Nothing decided yet.'}</p>}
        <ul className="mt-2">
          {decided.map((c) => (
            <li key={c.id} className="flex items-baseline justify-between gap-6 py-3">
              <div className="min-w-0">
                <div className="t-body line-clamp-2 text-ink">{headlineOf(c, state)}</div>
                <div className="t-small text-ink-3">
                  {DECIDED[c.status]}{c.ui?.at ? ` · ${fmtDay(c.ui.at)} ${fmtTime(c.ui.at)}` : ''}
                </div>
              </div>
              {automatedBy.has(c.id) ? (
                <span className="t-small dot-routine max-w-[45%] shrink-0 text-right text-routine">‘{automatedBy.get(c.id)}’</span>
              ) : (
                <button className="t-small uline shrink-0 disabled:opacity-60" disabled={!!writing} onClick={() => void suggest(c.id)}>
                  Handle cases like this
                </button>
              )}
            </li>
          ))}
        </ul>
      </section>

      <ProposalSheet items={review} ctx={state} onClose={() => setReview(null)} onChanged={changed} />
    </main>
  )
}

// Shapes of /api/routines (src/ask_soony/routines.py) and small helpers shared by the routine UI.

export type Field =
  | 'evidence' | 'headline' | 'option_action' | 'option_to' | 'supplier_name' | 'kind'
  | 'hours_left' | 'waiting_hours' | 'has_reply' | 'reply_after_launch' | 'silent_hours'
export type Channel = 'phone' | 'teams' | 'both'
/** What a routine looks at on each check. Missing means open decisions. */
export type Trigger = 'decisions' | 'waiting' | 'shipments'
/** How much a routine may do on its own. Missing means "tell". */
export type Mode = 'ask' | 'tell' | 'quiet'
export type StepKind = 'carry_out' | 'notify' | 'log' | 'chase' | 'call' | 'ask_status'

export interface Cond {
  id: string; field: Field; op: 'contains' | 'is' | 'any_of' | 'lt' | 'gt'; value: string | number | boolean; text: string
}
export interface Step {
  id: string
  do: StepKind
  text: string
  match?: { to?: string; action_contains?: string }
  channel?: Channel
  message?: string
}
export interface Spec { on?: Trigger; when: Cond[]; then: Step[] }

export interface Did {
  do: StepKind
  card?: string; shipment?: string; option?: string; text?: string; channel?: Channel; status?: string; dry?: boolean
}
export interface Run { at: string; ok: boolean; dry?: boolean; result?: unknown; error?: string; log?: string[]; did?: Did[] }
export interface Routine {
  id: string; name: string; description: string; spec?: Spec | null; code: string; enabled: boolean
  mode?: Mode
  created_from?: string | null; created_at?: string; runs?: Run[]; handled?: number; note?: string
}

/** Something a routine in "ask me" mode prepared and waits to be confirmed (GET /api/routines/proposals). */
export interface Proposal {
  id: string
  routine_id: string
  routine_name: string
  card_id?: string | null
  shipment_id?: string | null
  step: { do: StepKind | string; text?: string; channel?: Channel; [k: string]: unknown }
  preview_text?: string | null
  created_at?: string
  status: 'pending' | 'done' | 'skipped'
}
/** A routine that matches a card (GET /api/routines/would-handle). */
export interface WouldHandle { routine_id: string; routine_name: string; mode?: Mode; enabled: boolean }

export const MODES: { key: Mode; label: string; hint: string }[] = [
  { key: 'ask', label: 'Ask me', hint: 'Prepares it, you confirm with one tap' },
  { key: 'tell', label: 'Do it and tell me', hint: 'Does it and tells you' },
  { key: 'quiet', label: 'Do it quietly', hint: 'Does it, you see it in Handled for you' },
]
export const modeOf = (r: Pick<Routine, 'mode'>): Mode => (r.mode === 'ask' || r.mode === 'quiet' ? r.mode : 'tell')

/** The trigger node: what the routine looks at, in the buyer's words. */
export function triggerText(on?: Trigger): { title: string; text: string } {
  if (on === 'waiting') return { title: 'Messages still waiting for an answer', text: 'Every portal check, the emails we sent that have no reply yet' }
  if (on === 'shipments') return { title: 'Shipments that stopped updating', text: 'Every portal check, shipments with no new status for a while' }
  return { title: 'Every portal check · open decisions', text: 'New files, replies and open decisions, about every minute' }
}

const hoursWord = (v: unknown) => {
  const n = Number(v)
  if (!Number.isFinite(n)) return String(v)
  return n < 1 ? `${Math.round(n * 60)} min` : `${Math.round(n * 10) / 10} h`
}
const yes = (v: unknown) => v === true || /^(yes|true|1)$/i.test(String(v))

/**
 * A condition as a buyer reads it. The recipe's own text wins; the numeric and yes/no fields get
 * plain words when it is missing, so a field name never reaches the screen.
 */
export function condWords(c: Cond): string {
  if (c.text?.trim()) return c.text
  const more = c.op === 'gt'
  switch (c.field) {
    case 'hours_left': return `${more ? 'More' : 'Less'} than ${hoursWord(c.value)} before the deadline`
    case 'waiting_hours': return `No answer for ${more ? 'more' : 'less'} than ${hoursWord(c.value)}`
    case 'silent_hours': return `No shipment update for ${more ? 'more' : 'less'} than ${hoursWord(c.value)}`
    case 'has_reply': return yes(c.value) ? 'The supplier has answered' : 'The supplier has not answered yet'
    case 'reply_after_launch': return yes(c.value) ? 'The answer promises a date after launch' : 'The answer promises a date before launch'
    default: return `${c.op === 'contains' ? 'Mentions' : 'Is'} ${String(c.value)}`
  }
}

/** The fields the save, edit and preview endpoints take. */
export const body = (r: Routine) => ({
  id: r.id, name: r.name, description: r.description, spec: r.spec, created_from: r.created_from ?? null,
})

/** POST that keeps the server's reason on failure (FastAPI puts it in `detail`). */
export async function call<T>(url: string, payload: unknown = {}, method = 'POST'): Promise<T> {
  const r = await fetch(url, {
    method, headers: { 'Content-Type': 'application/json' }, body: method === 'DELETE' ? undefined : JSON.stringify(payload),
  })
  if (!r.ok) {
    let reason = ''
    try { reason = String((await r.json()).detail ?? '') } catch { /* not JSON */ }
    throw new Error(reason || `the server answered ${r.status}`)
  }
  return r.json()
}

export const newId = (prefix: string) => `${prefix}${Math.random().toString(36).slice(2, 8)}`

/** Steps a buyer can add with one click or drag. */
export const PALETTE: { key: string; label: string; make: () => Step }[] = [
  { key: 'phone', label: 'Tell me on my phone', make: () => ({ id: newId('s'), do: 'notify', channel: 'phone', message: '{headline}', text: 'Tell me on my phone' }) },
  { key: 'teams', label: 'Tell me on Teams', make: () => ({ id: newId('s'), do: 'notify', channel: 'teams', message: '{headline}', text: 'Tell me on Teams' }) },
  { key: 'call', label: 'Call me', make: () => ({ id: newId('s'), do: 'call', text: 'Call me' }) },
  { key: 'chase', label: 'Chase once if no answer', make: () => ({ id: newId('s'), do: 'chase', text: 'Chase once in the same thread if there is no answer' }) },
  { key: 'log', label: 'Note it in the history', make: () => ({ id: newId('s'), do: 'log', message: 'Handled by a routine: {headline}', text: 'Note it in the history' }) },
  { key: 'ask_status', label: 'Ask for a status', make: () => ({ id: newId('s'), do: 'ask_status', text: 'Ask the supplier for the shipment status' }) },
]

export function paletteKey(s: Step): string | null {
  if (s.do === 'log' || s.do === 'chase' || s.do === 'call' || s.do === 'ask_status') return s.do
  if (s.do === 'notify' && (s.channel === 'phone' || s.channel === 'teams')) return s.channel
  return null
}

const where = (c?: Channel) => (c === 'phone' ? ' on your phone' : c === 'teams' ? ' on Teams' : '')

export type LineKind = 'send' | 'tell' | 'note' | 'chase' | 'call' | 'ask_status'

/** One line per thing a run did (or would do, in a test run). */
export function didLines(run: Run, spec?: Spec | null): { kind: LineKind; channel?: Channel; text: string }[] {
  const out: { kind: LineKind; channel?: Channel; text: string }[] = []
  for (const d of run.did ?? []) {
    const about = d.text || d.option || ''
    if (d.do === 'carry_out') {
      out.push({ kind: 'send', text: `${d.dry ? 'Would send' : 'Sent'}: ${d.option ?? 'the message'}` })
    } else if (d.do === 'chase') {
      out.push({ kind: 'chase', text: `${d.dry ? 'Would chase' : 'Chased'} once in the same thread${about ? `: ${about}` : ''}` })
    } else if (d.do === 'call') {
      out.push({ kind: 'call', text: `${d.dry ? 'Would call you' : 'Called you'}${about ? `: ${about}` : ''}` })
    } else if (d.do === 'ask_status') {
      out.push({ kind: 'ask_status', text: `${d.dry ? 'Would ask' : 'Asked'} for a status${about ? `: ${about}` : ''}` })
    } else if (d.do === 'log') {
      out.push({ kind: 'note', text: `${d.dry ? 'Would note' : 'Noted'}: ${about}` })
    } else {
      out.push({ kind: 'tell', channel: d.channel, text: `${d.dry ? 'Would tell you' : 'Told you'}${where(d.channel)}: ${d.text ?? ''}` })
    }
  }
  // Lines from "note it" steps; the carry-out bookkeeping lines are already covered above.
  const sendTexts = (spec?.then ?? []).filter((s) => s.do === 'carry_out').map((s) => s.text)
  for (const line of run.log ?? []) {
    if (!line || sendTexts.some((t) => line.startsWith(t))) continue
    out.push({ kind: 'note', text: `${run.dry ? 'Would note' : 'Noted'}: ${line}` })
  }
  return out
}

/** "Told you about 1 card", "Sent 2 messages", "Nothing to do" for the stats line. */
export function summarise(run: Run): string {
  if (!run.ok) return 'The last run failed'
  const did = run.did ?? []
  const n = (k: StepKind) => did.filter((d) => d.do === k).length
  const sent = n('carry_out')
  const told = new Set(did.filter((d) => d.do === 'notify').map((d) => d.card)).size
  const s = (k: number) => (k === 1 ? '' : 's')
  const parts: string[] = []
  if (sent) parts.push(`sent ${sent} message${s(sent)}`)
  if (n('chase')) parts.push(`chased ${n('chase')} time${s(n('chase'))}`)
  if (n('ask_status')) parts.push(`asked for ${n('ask_status')} status${n('ask_status') === 1 ? '' : 'es'}`)
  if (n('call')) parts.push(`called you ${n('call') === 1 ? 'once' : `${n('call')} times`}`)
  if (told) parts.push(`told you about ${told} card${s(told)}`)
  const out = parts.join(', ')
  return out ? out[0].toUpperCase() + out.slice(1) : 'Nothing to do'
}

import { useSyncExternalStore } from 'react'
import { call, type Mode, type Proposal, type Routine, type Run, type WouldHandle } from './types'

// What the routines prepared for the buyer, shared by the Routines sheet, Today and Plan:
// proposals waiting for an OK, routines that would handle a card, repeated decisions worth a
// routine, and actions undone on this screen. Refreshed on the app's own refresh (see `refreshLive`), never on its
// own timer. Endpoints that are not there yet (404) simply count as empty.

/** A routine the voice assistant drafted during a call (GET /api/routines/drafts). */
export interface VoiceDraft { card_id: string; instruction?: string; at?: string; via?: string; routine: Routine; preview?: Run }

/** Past decisions made the same way at least twice, with no routine for them yet (GET /api/routines/suggestions). */
export interface Suggestion {
  key: string
  count: number
  card_ids: string[]
  decision: 'approve' | 'escalate' | 'dismiss'
  /** The option's action, as the agents wrote it ("Ask ... to ..."); null for escalate and dismiss. */
  action?: string | null
  /** The latest card's headline. */
  label?: string | null
  supplier?: string | null
  last_card_id: string
  last_at: string
}

interface Live {
  proposals: Proposal[]
  /** Voice drafts not hidden on this device and not saved as a routine yet. */
  drafts: VoiceDraft[]
  would: Record<string, WouldHandle[]>
  /** Action id -> "undone" or the reason it could not be undone. */
  undo: Record<string, { ok: boolean; reason?: string }>
  /** Proposals the buyer just accepted or skipped, hidden before the server agrees. */
  settled: Set<string>
  /** Repeated decisions worth a routine, newest first. */
  suggestions: Suggestion[]
}

const HIDDEN_KEY = 'ask-soony.hidden-routine-drafts'
function readHidden(): Set<string> {
  try { return new Set(JSON.parse(localStorage.getItem(HIDDEN_KEY) ?? '[]') as string[]) } catch { return new Set() }
}
let hidden = readHidden()
let allDrafts: VoiceDraft[] = []
const visibleDrafts = () => allDrafts.filter((d) => !hidden.has(d.routine.id))

let live: Live = { proposals: [], drafts: [], would: {}, undo: {}, settled: new Set(), suggestions: [] }
const subs = new Set<() => void>()
const set = (next: Partial<Live>) => { live = { ...live, ...next }; subs.forEach((f) => f()) }
const subscribe = (f: () => void) => { subs.add(f); return () => { subs.delete(f) } }

async function getJson<T>(url: string): Promise<T | null> {
  try {
    const r = await fetch(url)
    return r.ok ? ((await r.json()) as T) : null
  } catch { return null }
}

let lastAt = 0
let inflight: Promise<void> | null = null
/** Fetch proposals and would-handle; calls within `minMs` of the last one are skipped. */
export function refreshLive(minMs = 4000): Promise<void> {
  if (inflight) return inflight
  if (Date.now() - lastAt < minMs) return Promise.resolve()
  lastAt = Date.now()
  inflight = (async () => {
    const [p, w, d, s] = await Promise.all([
      getJson<{ proposals?: Proposal[] }>('/api/routines/proposals'),
      getJson<Record<string, WouldHandle[]>>('/api/routines/would-handle'),
      getJson<{ drafts?: VoiceDraft[] }>('/api/routines/drafts'),
      getJson<{ suggestions?: Suggestion[] }>('/api/routines/suggestions'),
    ])
    const suggestions = Array.isArray(s?.suggestions)
      ? s.suggestions.filter((x) => x && x.count >= 2 && Array.isArray(x.card_ids) && x.last_card_id)
      : live.suggestions
    if (d) allDrafts = (d.drafts ?? []).filter((x) => x?.routine?.id)
    const proposals = Array.isArray(p?.proposals) ? p.proposals.filter((x) => x && x.id) : []
    const would: Record<string, WouldHandle[]> = {}
    for (const [k, v] of Object.entries(w ?? {})) if (Array.isArray(v) && v.length) would[k] = v
    // Forget settled ids the server no longer lists as pending.
    const pending = new Set(proposals.filter((x) => x.status === 'pending').map((x) => x.id))
    const settled = new Set([...live.settled].filter((id) => pending.has(id)))
    set({ proposals, would, settled, suggestions, drafts: visibleDrafts() })
  })().finally(() => { inflight = null })
  return inflight
}

export function useLive(): Live {
  return useSyncExternalStore(subscribe, () => live)
}

/** Pending proposals not yet answered on this screen; for one card when `cardId` is given. */
export function pendingOf(l: Live, cardId?: string): Proposal[] {
  return l.proposals.filter(
    (p) => (p.status ?? 'pending') === 'pending' && !l.settled.has(p.id) && (cardId == null || p.card_id === cardId),
  )
}

/** The suggestion a decided card belongs to (read outside React, right after a decision). */
export function suggestionFor(cardId: string): Suggestion | null {
  return live.suggestions.find((x) => x.card_ids.includes(cardId) && x.count >= 2) ?? null
}

/** Hide a voice draft on this device (turned on, or "Not now"). */
export function hideDraft(routineId: string) {
  hidden = new Set(hidden).add(routineId)
  try { localStorage.setItem(HIDDEN_KEY, JSON.stringify([...hidden])) } catch { /* private mode */ }
  set({ drafts: visibleDrafts() })
}

/** Ask the server again right away (after a change on this screen). */
export function refreshNow(): Promise<void> {
  lastAt = 0
  return refreshLive(0)
}

export async function answerProposal(id: string, how: 'accept' | 'skip'): Promise<void> {
  const r = await call<{ ok?: boolean; result?: { error?: string } }>(`/api/routines/proposals/${encodeURIComponent(id)}/${how}`)
  // Accept answers 200 with ok: false when the step itself did not go through.
  if (r && r.ok === false) throw new Error(r.result?.error || 'it did not go through')
  // An accepted one stays a moment so its "Done" shows.
  window.setTimeout(() => {
    set({ settled: new Set(live.settled).add(id) })
    lastAt = 0
    void refreshLive()
  }, how === 'accept' ? 1500 : 0)
}

/** Undo a routine's action; remembers the outcome so the list and the pane agree. */
export async function undoAction(actionId: string): Promise<{ ok: boolean; reason?: string }> {
  let out: { ok: boolean; reason?: string }
  try {
    const r = await call<{ ok?: boolean; undone?: boolean; reason?: string }>(`/api/routines/actions/${encodeURIComponent(actionId)}/undo`)
    out = r.ok && r.undone !== false ? { ok: true } : { ok: false, reason: r.reason || 'This can no longer be undone.' }
  } catch (e) {
    const m = (e as Error).message
    out = { ok: false, reason: /404|not found/i.test(m) ? 'Undo is not available yet.' : m }
  }
  set({ undo: { ...live.undo, [actionId]: out } })
  return out
}

export async function setMode(routineId: string, mode: Mode): Promise<void> {
  await call(`/api/routines/${encodeURIComponent(routineId)}/mode`, { mode })
  lastAt = 0
  void refreshLive()
}

export async function setEnabled(routineId: string, enabled: boolean): Promise<void> {
  await call(`/api/routines/${encodeURIComponent(routineId)}/toggle`, { enabled })
  lastAt = 0
  void refreshLive()
}

/** Navigate inside the app from anywhere (the app listens to popstate). */
export function goTo(path: string) {
  window.history.pushState(null, '', path)
  window.dispatchEvent(new PopStateEvent('popstate'))
  window.scrollTo(0, 0)
}

content.content:
expressed with the fields above (for example a filter the data does not have), leave the recipe
unchanged and say so in "note". Answer with JSON only: {{"name": "...", "description": "...",
"spec": <the new recipe>, "note": "<empty, or one sentence for the buyer>"}}
Plain buyer language only, no internal field names or codes."""


# ---------------------------------------------------------------- storage


def _all() -> list[dict]:
    from ask_soony import api

    return api.read_list("routines.json")


def _save(items: list[dict]) -> None:
    from ask_soony import api

    api.write_json("routines.json", items)
    _would_cache.clear()


def _get(rid: str) -> dict:
    r = next((x for x in _all() if x.get("id") == rid), None)
    if r is None:
        raise HTTPException(404, "unknown routine")
    return r


def mode_of(routine: dict) -> str:
    m = routine.get("mode")
    return m if m in MODES else "tell"


# ---------------------------------------------------------------- building blocks


def _hours(a, b) -> float | None:
    """Hours from datetime a to datetime b, one decimal; None if either is missing."""
    if a is None or b is None:
        return None


def _push(title: str, body: str, card_id: str | None = None) -> None:
    try:
        from ask_soony import push

        push.send(title, body, card_id or None)
    except Exception:  # no devices or no keys: the action is in the history anyway
        pass


def _append_action(action: dict) -> dict:
    from ask_soony import api

    action = {"id": uuid.uuid4().hex[:10], "at": api.now().isoformat(), **action}
    with api._lock:
        actions = api.read_list("actions.json")
        actions.append(action)
        api.write_json("actions.json", actions)
    return action


def _place_call(text: str, card: dict | None, who: str) -> dict:
def run(routine: dict, dry: bool = False, state: dict | None = None) -> dict:
    """Run one routine in the Monty sandbox; returns the run record."""
    from pydantic_monty import CollectString, ExternalModule, Monty

    ctx = _Run(routine, dry, state)
    module = ExternalModule(
        {
            "open_cards": ctx.open_cards,
            "waiting_cards": ctx.waiting_cards,
            "replied_cards": ctx.replied_cards,
            "silent_shipments": ctx.silent_shipments,
            "carry_out": ctx.carry_out,
            "chase": ctx.chase,
            "ask_status": ctx.ask_status,
            "call": ctx.call,
            "notify": ctx.notify,
            "log": ctx.log,
            "first_time": ctx.first_time,
            "now": ctx.now,
        },
        stubs=STUBS,
    )
    printed = CollectString(max_bytes=20_000)
    record: dict = {"at": ctx.now(), "dry": dry, "mode": ctx.mode}
    try:
        with Monty() as pool:
            with pool.checkout(
                external_modules={"soony": module},
                type_check=True,
                limits={"max_feed_duration_secs": 10, "max_memory": 64 * 1024 * 1024},
            ) as session:
                result = session.feed_run(routine["code"], print_callback=printed)
        record.update(ok=True, result=result if isinstance(result, (int, str, float)) else None)
    except Exception as exc:  # syntax, type or runtime errors from the sandbox
        record.update(ok=False, error=str(exc)[:1500])
    output = str(getattr(printed, "output", "") or "")
    record.update(log=ctx.lines + ([output.strip()] if output.strip() else []), did=ctx.did)
    if not dry:
        routine["seen"] = sorted(ctx.seen)
    return record


# ---------------------------------------------------------------- proposals (mode "ask")


def _proposals() -> list[dict]:
    from ask_soony import api

    return api.read_list(PROPOSALS)


def propose(routine: dict, step: dict, preview: str) -> str:
    """Store one outgoing action as a pending proposal; the same pending one is not repeated."""
    from ask_soony import api

    with _plock:
        items = _proposals()
        same = next(
            (
                p
                for p in items
                if p.get("status") == "pending"
                and p.get("routine_id") == routine.get("id")
                and p.get("step") == step
            ),
            None,
        )
        if same:
            return str(same["id"])
        p = {
            "id": uuid.uuid4().hex[:8],
            "routine_id": routine.get("id"),
            "routine_name": routine.get("name"),
            **({"card_id": step["card"]} if step.get("card") else {}),
            **({"shipment_id": step["shipment"]} if step.get("shipment") else {}),
            "step": step,
            "preview_text": preview,
            "created_at": api.now().isoformat(),
            "status": "pending",
        }
        api.write_json(PROPOSALS, items + [p])
    _push(f"Routine asks: {routine.get('name')}", preview.split("\n")[0][:160], step.get("card"))
    return p["id"]


def accept(pid: str) -> dict:
    """Carry out one proposal now, through the same building blocks as a real run; once only."""
    from ask_soony import api

    with _plock:
        items = _proposals()
        p = next((x for x in items if x.get("id") == pid), None)
        if p is None:
            raise HTTPException(404, "unknown proposal")
        if p.get("status") != "pending":
            return {"ok": False, "result": {"error": f"already {p.get('status')}"}}
        p["status"] = "running"
        api.write_json(PROPOSALS, items)
    routine = next(
        (r for r in _all() if r.get("id") == p.get("routine_id")),
        {"id": p.get("routine_id"), "name": p.get("routine_name") or "Routine"},
    )
    st = p.get("step") or {}
    result: dict
    try:
        ctx = _Run(routine, dry=False)
        ctx.accepting = True
        do = st.get("do")
        if do == "carry_out":
            result = ctx.carry_out(
                str(st.get("card")),
                int(st.get("option_index") or 0),
                str(st.get("reason") or "accepted"),
            )
        elif do == "chase":
            result = ctx.chase(str(st.get("card")), str(st.get("message") or ""))
        elif do == "ask_status":
            result = ctx.ask_status(str(st.get("shipment")), str(st.get("message") or ""))
        elif do == "call":
            result = ctx.call(
                str(st.get("message") or ""),
                str(st.get("card") or ""),
                str(st.get("who") or "responsible"),
            )
        else:
            result = _no(f"cannot carry out {do}")
    except Exception as exc:
        result = _no(str(exc)[:300], "error")
    with _plock:
        items = _proposals()
        for x in items:
            if x.get("id") == pid:
                x["status"] = "done" if result.get("ok") else "pending"
                if result.get("ok"):
                    x["done_at"] = api.now().isoformat()
                    x["result"] = result
                else:
                    x["error"] = result.get("error")
        api.write_json(PROPOSALS, items)
    _would_cache.clear()
    return {"ok": bool(result.get("ok")), "result": result}


def skip(pid: str) -> dict:
    from ask_soony import api

    with _plock:
        items = _proposals()
        p = next((x for x in items if x.get("id") == pid), None)
        if p is None:
            raise HTTPException(404, "unknown proposal")
        if p.get("status") == "pending":
            p["status"] = "skipped"
            p["skipped_at"] = api.now().isoformat()
            api.write_json(PROPOSALS, items)
    return {"ok": True, "proposal": p}


# ---------------------------------------------------------------- undo


EMAIL_GONE = "The email already went out. Send a correction instead?"
CALL_GONE = "The call already happened."


def undo(action_id: str) -> dict:
    """
    Undo one recorded action: decisions without an email go back to open; mail and calls
    cannot be taken back.
    """
    from ask_soony import api

    with api._lock:
        actions = api.read_list("actions.json")
        act = next((a for a in actions if str(a.get("id")) == action_id), None)
        if act is None:
            raise HTTPException(404, "unknown action")
        if act.get("kind") == "undo" or any(
            a.get("kind") == "undo" and a.get("undoes") == action_id for a in actions
        ):
            return {"ok": False, "reason": "Already undone."}
        if act.get("kind") == "call" or act.get("channel") == "call":
            return {"ok": False, "reason": CALL_GONE}
        if (
            act.get("message_id")
            or act.get("status") == "sent"
            or act.get("kind") in ("chase", "ask_status")
        ):
            return {"ok": False, "reason": EMAIL_GONE}
        if act.get("kind") == "reply":
            return {"ok": False, "reason": "A supplier's reply cannot be undone."}
        card_id = str(act.get("decision_id") or "")
        sts = api.read_json("decision_status.json", {})
        entry = sts.get(card_id)
        if entry and entry.get("action_id") not in (None, action_id):
            return {"ok": False, "reason": "Something newer happened on this decision since."}
        sts.pop(card_id, None)
        api.write_json("decision_status.json", sts)
        undo_act = {
            "id": uuid.uuid4().hex[:10],
            "decision_id": card_id,
            "at": api.now().isoformat(),
            "kind": "undo",
            "undoes": action_id,
            "status": "open",
            "via": "inbox",
        }
        actions.append(undo_act)
        api.write_json("actions.json", actions)
    _would_cache.clear()
    return {"ok": True, "undone": True, "card_id": card_id, "action": undo_act}


# ---------------------------------------------------------------- would handle


_would_cache: dict = {}
WOULD_TTL = 30.0


def would_handle() -> dict[str, list[dict]]:
    """Which routines that are off, or only ask, would act on which open card (dry runs)."""
    hit = _would_cache.get("v")
    if hit and time.monotonic() - hit[0] < WOULD_TTL:
        return hit[1]
    from ask_soony import api

    out: dict[str, list[dict]] = {}
    candidates = [
        r for r in _all() if r.get("code") and (not r.get("enabled") or mode_of(r) == "ask")
    ]
    if candidates:
        state = api.build_state()
        for r in candidates:
            try:
                rec = run(dict(r), dry=True, state=state)
            except Exception as exc:
                log.warning("would-handle %s failed: %s", r.get("id"), exc)
                continue
            info = {
                "routine_id": r.get("id"),
                "routine_name": r.get("name"),
                "mode": mode_of(r),
                "enabled": bool(r.get("enabled")),
            }
            for cid in {str(d["card"]) for d in rec.get("did") or [] if d.get("card")}:
                out.setdefault(cid, []).append(info)
    _would_cache["v"] = (time.monotonic(), out)
    return out


# ---------------------------------------------------------------- recipe (spec) and compiler
#
# The writer agent returns a recipe, not code: what it watches ("on"), conditions ("when") and
# steps ("then") in plain phrases plus a few machine fields. compile_spec() turns it into the
# sandbox code, so edits by text or drag and drop change data only, and the money/plan guard is
# always compiled in.

TRIGGERS = ("decisions", "waiting", "replies", "shipments")
TEXT_FIELDS = {"evidence", "headline", "option_action", "option_to", "supplier_name", "kind"}
NUM_FIELDS = {"hours_left", "waiting_hours", "silent_hours"}
def preview(routine: dict) -> dict:
    """Compile (if it has a recipe) and dry-run a routine on today's inbox."""
    if routine.get("spec"):
        routine["code"] = compile_spec(routine["spec"])
    return run(routine, dry=True)


def suggest(card_id: str) -> dict:
    """Draft a routine from the person's last decision on this card, checked by a dry run."""
    from ask_soony import api

    card = next((c for c in api.build_state()["cards"] if c["id"] == card_id), None)
    if card is None:
        raise HTTPException(404, "unknown card")
    act = next(
        (
            a
            for a in reversed(api.read_list("actions.json"))
            if str(a.get("decision_id")) == card_id
            and a.get("kind") in ("approve", "escalate", "dismiss")
        ),
        None,
    )
    if act is None:
        raise HTTPException(409, "decide this card first, then automate it")
    action = {
        "approve": f"approved: {act.get('action')} (to {act.get('to')}, {act.get('status')})",
        "escalate": f"escalated it to {act.get('to')}",
        "dismiss": "dismissed it",
    }[act["kind"]]
    prompt = WRITER_PROMPT.format(
        spec_help=SPEC_HELP, card=json.dumps(_card_view(card), ensure_ascii=False), action=action
    )
    draft = _ask_for_spec(prompt)
    # Trust ladder: a new routine prepares its actions for one-tap approval until switched up.
    draft.update(id=uuid.uuid4().hex[:8], created_from=card_id, enabled=False, mode="ask")
    return {"routine": draft, "preview": run(draft, dry=True)}


def edit(routine: dict, instruction: str) -> dict:
    """Change a routine (draft or saved) as the buyer asks; returns the new version and its test
    run. Nothing is saved here."""
    current = {k: routine.get(k) for k in ("name", "description", "spec")}
    prompt = EDIT_PROMPT.format(
        spec_help=SPEC_HELP,
        routine=json.dumps(current, ensure_ascii=False),
        instruction=instruction.replace('"', "'")[:300],
    )
    new = _ask_for_spec(prompt, fallback={**current, "code": routine.get("code", "")})
    after = {**routine, **{k: new[k] for k in ("name", "description", "spec", "code")}}
    return {"after": after, "note": new.get("note", ""), "preview": run(after, dry=True)}


# ---------------------------------------------------------------- loop and routes


def _count_handled(rec: dict) -> int:
    return len({d.get("card") or d.get("shipment") for d in rec.get("did") or []} - {None, ""})


def run_enabled() -> list[dict]:
    with _lock:
        items = _all()
        records = []
        for r in items:
            if not r.get("enabled"):
                continue
            rec = run(r)
            r["runs"] = ([rec] + (r.get("runs") or []))[:20]
            r["handled"] = int(r.get("handled") or 0) + _count_handled(rec)
            records.append({"routine": r["id"], **rec})
        _save(items)
    return records


def _loop(interval: int) -> None:
    while True:
        try:
            for rec in run_enabled():
                if rec.get("did") or not rec.get("ok"):
                    log.info("routine %s: %s", rec["routine"], rec.get("did") or rec.get("error"))
        except Exception as exc:
            log.warning("routines failed: %s", exc)
        time.sleep(interval)


def start_background() -> None:
    interval = int(os.environ.get("ASK_ROUTINES_SECONDS", "60"))
    threading.Thread(target=_loop, args=(interval,), daemon=True, name="routines").start()


