            'right-2 top-1/2 h-9 w-9 -translate-y-1/2',
            'lg:-right-2.5 lg:-top-2.5 lg:h-6 lg:w-6 lg:translate-y-0 lg:opacity-0 lg:group-focus-within:opacity-100 lg:group-hover:opacity-100',
